// === Tab: mySketch ===
let skull
let contactShadowRenderer
let eyeball
let face
let faceShader
let hair
let hairShader
let brain
let brainShader

function setup() {
	createCanvas(600, 600, WEBGL)
	pixelDensity(2)
	contactShadowRenderer = createContactShadowRenderer()
	contactShadowRenderer.setShadowSamples(20)
	contactShadowRenderer.setSearchRadius(200)
	contactShadowRenderer.setBlurRadius(50)
	contactShadowRenderer.setTintColor(color(0, 0, 0))

	eyeball = createFramebuffer({
		width: 100,
		height: 50,
		density: 3
	})
	eyeball.draw(() => {
		background(255)
		noStroke()
		fill('#28997D')
		circle(0, 0, 15)
		fill(0)
		circle(0, 0, 7)
	})

	skull = csg(() => {
		translate(0, -20)
		scale(0.9, 0.8, 1)
		sphere(200, 24, 24)
	}).union(() => {
		translate(0, 50, 50)
		cylinder(120, 130, 12, 1)
	}).subtract(() => {
		translate(-50, 20, 200)
		sphere(70, 6, 6)
	}).subtract(() => {
		translate(50, 20, 200)
		sphere(70, 6, 6)
	}).union(() => {
		translate(0, 150, 50)
		cylinder(110, 40, 12, 1)
	}).union(() => {
		for (let i = 0; i < 6; i++) {
			push()
			const r = 100
			const angle = map(i, 0, 5, -1, 1) * PI * 0.2 + PI / 2
			translate(r * cos(angle), 120, 50 + r * sin(angle))
			cylinder(20, 10, 6, 1)
			pop()
		}
	}).done()

	face = csg(() => {
		translate(0, -20)
		scale(0.85, 0.8, 0.95)
		sphere(220, 24, 24)
	}).union(() => {
		translate(0, 50, 50)
		scale(1, 1.25, 1)
		sphere(150, 24, 24)
	}).union(() => {
		translate(0, 30, 200)
		rotateX(PI * 0.1)
		scale(1, 2.5, 1)
		sphere(25)
	}).union(() => {
		translate(190, 50, 0)
		rotateY(PI * 0.2)
		scale(1, 1.2, 0.35)
		sphere(40)
	}).union(() => {
		translate(-190, 50, 0)
		rotateY(PI * -0.2)
		scale(1, 1.2, 0.35)
		sphere(40)
	}).done()

	faceShader = baseMaterialShader().modify(() => {
		getPixelInputs((inputs) => {
			// Fake subsurface scattering
			inputs.ambientMaterial = mix(
				[...color('#FD7D7D').array()].xyz,
				inputs.ambientMaterial,
				abs(inputs.normal.z)
			)
			return inputs
		})
	})

	hair = buildGeometry(() => {
		beginShape(QUAD_STRIP)
		for (let y = 0; y > -100; y -= 2) {
			var angle = y / -100 * PI * 5
			var r = map(y, 0, -100, 20, 0)
			const x = r * cos(angle)
			const z = r * sin(angle)
			for (const side of [-1, 1]) {
				vertex(x, y, z + side * 5)
			}
		}
		endShape()
	})
	hair.computeNormals()

	hairShader = baseMaterialShader().modify(() => {
		function rand(seed) {
			return fract(sin(dot(seed, [12.9898, 78.233])) * 43758.5453123);
		}

		function randomPositionOnSphere() {
			let id = instanceID();
			let theta = rand([id, 0.1234]) * TWO_PI;
			let phi = rand([id, 3.321]) * PI;

			var r = 1;
			var x = r * sin(phi) * cos(theta);
			let y = r * cos(phi);
			var z = r * sin(phi) * sin(theta);
			return [x, y, z];
		}

		const rotateAxisAngle = (axis, angle, pos) => {
			const a = normalize(axis)
			const s = sin(angle)
			const c = cos(angle)
			const oc = 1 - c

			const r1 = [oc * a.x * a.x + c, oc * a.x * a.y - a.z * s, oc * a.z * a.x + a.y * s]
			const r2 = [oc * a.x * a.y + a.z * s, oc * a.y * a.y + c, oc * a.y * a.z - a.x * s]
			const r3 = [oc * a.z * a.x - a.y * s, oc * a.y * a.z + a.x * s, oc * a.z * a.z + c]

			return [
				dot(pos, r1),
				dot(pos, r2),
				dot(pos, r3)
			]
		}

		getWorldInputs((inputs) => {
			let pos = randomPositionOnSphere()
			pos.y = -abs(pos.y)
			let axis = cross([0, -1, 0], pos)
			var angle = acos(-pos.y)

			let newPos = rotateAxisAngle([0, 1, 0], instanceID() * 0.1, inputs.position)
			newPos = rotateAxisAngle(axis, angle * 0.8, newPos + [0, -150, 0])
			inputs.position = newPos
			return inputs
		})

		getPixelInputs((inputs) => {
			let n = inputs.normal
			n.z = abs(n.z)
			inputs.normal = n
			return inputs
		})
	})

	brain = csg(() => {
		translate(0, 20, -100)
		scale(1.5, 1, 0.8)
		sphere(80)
	}).union(() => {
		translate(-50, 0)
		scale(0.85, 0.8, 1.5)
		sphere(100)
	}).union(() => {
		translate(50, 0)
		scale(0.85, 0.8, 1.5)
		sphere(100)
	}).done()

	brainShader = baseMaterialShader().modify(() => {
		let position = sharedVec3()
		getWorldInputs((inputs) => {
			position = inputs.position
			return inputs
		})
		getPixelInputs((inputs) => {
			let dir = normalize(position)
			var n = inputs.normal
			var s = 0.1
			noiseDetail(2, 0.5)
			n += 0.3 * [
				noise(position.x*s, position.y*s, position.z*s),
				noise(position.x*s, position.y*s, position.z*s + 100),
				noise(position.x*s, position.y*s, position.z*s + 200),
			]
			n = normalize(n)
			inputs.normal = n
			return inputs
		})
	})
}

function draw() {
	contactShadowRenderer.draw(() => {
		background(0)
		orbitControl()
		perspective(
			2 * atan(height / 2 / 800),
			width / height,
			// 0.1,
			map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 300, 1200, true),
			8000
		)

		noStroke()
		lights()
		model(skull)

		push()
		fill('#C78BD0')
		specularMaterial(255)
		shininess(150)
		shader(brainShader)
		scale(0.8)
		model(brain)
		pop()

		push()
		texture(eyeball)
		let t = millis()
		specularMaterial(255)
		shininess(100)
		push()
		translate(-55, 15, 195)
		rotateY(PI)
		rotateY(map(noise(t * 0.001), 0, 0.8, -1, 1) * PI * 0.2)
		rotateX(map(noise(t * 0.001, 100), 0, 0.8, -1, 1) * PI * 0.2)
		sphere(45)
		pop()
		push()
		translate(55, 15, 195)
		rotateY(PI)
		rotateY(map(noise(t * 0.001), 0, 0.8, -1, 1) * PI * 0.2)
		rotateX(map(noise(t * 0.001, 100), 0, 0.8, -1, 1) * PI * 0.2)
		sphere(45)
		pop()
		pop()

		push()
		translate(0, 120, 185)
		rotate(PI / 2)
		fill('#CA5656')
		cylinder(5, 80)
		pop()

		push()
		shader(faceShader)
		fill('#FDD1D1')
		model(face)
		pop()

		push()
		translate(0, -50)
		shader(hairShader)
		fill('#645648')
		specularMaterial('#645921')
		shininess(10)
		model(hair, 600)
		pop()
	})
}

